import os
import re
import logging

from taf.transport.ssh.exceptions import CommandExecutionError

from .exception import IpAndPortBindingError, InvalidRequestedAddress, SyslogInitializationError, StopSyslogException
from ute_common_util.decorators.retry import retry_until_no_exception_or_out_of_attempts


class Controller(object):
    """A class for preparing the environment and starting/stopping the syslog."""

    def __init__(self, ssh_connection, ssh_params, log_dir, log_name, ip, ports, file_limit, add_line_number=False, cli_prefix=None,
                 virtualenv_dir=None):
        """
        :param SSHConnection ssh_connection:        Connected SSHConnection object.
        :param dict          ssh_params:            dictionary containing ssh key-value for host_ip, username and password
        :param string        log_dir:               Path to the directory where syslog should be stored.
        :param string        log_name:              Name of the log file where captured data should be stored.
        :param string        ip:                    IP address of remote PC.
        :param list          ports:                 List of ports to listen.
        :param integer       file_limit:            Max. size of log file. 0 means unlimited.
        :param bool          add_line_number:       Adds line numbers to the generated logs. Defaults to False
        """
        self._ssh_connection = ssh_connection
        self._ssh_params = ssh_params
        self._log_dir = log_dir
        self._log_name = log_name
        self._file_limit = file_limit
        self._log_path = os.path.join(self._log_dir, self._log_name)
        self._ip = ip
        self._ports = ports
        self._add_line_number = ' -a' if add_line_number else ''
        self._pid = None
        self._cli_prefix = '{} '.format(cli_prefix) if cli_prefix else ''
        self._virtualenv_dir = virtualenv_dir

    @property
    def connection(self):
        """Returns the actual SSH client object."""
        return self._ssh_connection

    @property
    def ssh_params(self):
        """Returns the SSH parameters dictionary."""
        return self._ssh_params

    @property
    def log_path(self):
        """Returns the provide log directory"""
        return os.path.join(self._log_dir, self._log_name)

    @property
    def log_pattern(self):
        """Returns pattern to select all log files."""
        if self._file_limit > 0:
            return self._create_multi_log_pattern()
        return self._log_path

    def start(self):
        """Start the syslog service."""
        exc = self._start_syslog()
        if exc:
            self._stop_and_raise_exception(exc)
        logging.info('Syslog started successfully!\nSylog pid: {}'.format(self._pid))

    @retry_until_no_exception_or_out_of_attempts(attempts=3)
    def stop(self):
        """Stop the syslog service."""
        if self._pid is None:
            logging.info('Attempting to stop syslog but no instance found.')
        else:
            logging.info('Attempting to stop syslog (PID: {}) instance...'.format(self._pid))
            self._ssh_connection.execute('kill -9 {}'.format(self._pid), timeout=5)
            if self._pid_exists():
                raise StopSyslogException("Syslog can't be stopped!")
            else:
                logging.info('Syslog (PID: {}) stopped!'.format(self._pid))
                self._pid = None

    def configure(self, ip=None, ports=None):
        """Configure optional settings for Controller.

        :param string ip:    Bind IP address.
        :param list   ports: List of ports used to collect syslog data.
        """
        self._ip = ip or self._ip
        self._ports = ports or self._ports

    @retry_until_no_exception_or_out_of_attempts(attempts=3, delay=1)
    def _start_syslog(self):
        try:
            out = ''
            regexp = re.compile(r'Syslog started!|error: \[Errno \d{1,3}\]|Error')
            process = self._ssh_connection.send_command('{}\n'.format(self._build_syslog_cmd()))
            while not regexp.search(out):
                out += process.read_output_until("\n")
            logging.debug(out)
            self._pid = self._get_pid_from_console_output(out)
            return self._validate_syslog_output(out)

        except CommandExecutionError as e:
            self._pid = self._get_pid_from_console_output(str(e))
            self._stop_and_raise_exception(SyslogInitializationError(str(e)))

        except Exception as e:
            return e

    def _validate_syslog_output(self, console_output):
        if 'Syslog started!' not in console_output:
            if 'Errno 98' in console_output:
                netstat_output = self._get_netstat()
                err = 'Ports {} are already bound by other application/s'.format(self._ports)
                return IpAndPortBindingError('{}\n{}'.format(err, netstat_output).strip())
            elif 'Errno 99' in console_output:
                return InvalidRequestedAddress('{} address is missing.'.format(self._ip))
            elif 'Errno' in console_output:
                return SyslogInitializationError("Error in syslog:\n" + console_output)
            else:
                return SyslogInitializationError("Unknown error:\n" + console_output)

    def _pid_exists(self):
        fields = ("pid", "ppid", "user", "stat", "pcpu", "size", "priority", "comm")
        try:
            proc = self._ssh_connection.send_command("ps -p {} -o {} --no-headers".format(self._pid, ",".join(fields)), timeout=1.5)
            out = proc.read_output()
            if out:
                results = re.split(r"\s*", out.strip())
                logging.debug("  ".join([": ".join(i) for i in zip(fields, results)]))
                return True
            else:
                return False
        except CommandExecutionError:
            return True

    def _get_pid_from_console_output(self, console_output):
        return re.search('(Syslog pid: )(.*)', console_output).group(2).strip()

    def _stop_and_raise_exception(self, exc):
        self.stop()
        raise exc

    def _create_multi_log_pattern(self):
        result = self._log_path.rsplit(".", 1)
        if len(result) > 1:
            return "{}_*.{}".format(result[0], result[1])
        return "{}_*".format(self._log_path)

    def _change_ports_to_string(self):
        ports = [str(port) for port in self._ports]
        return ' '.join(ports)

    def _build_syslog_cmd(self):
        if self._virtualenv_dir is not None:
            ret = 'source {}/bin/activate; '.format(self._virtualenv_dir)
        else:
            ret = ''
        ret += '{}cli_syslog.py -d "{}" -l "{}" -i "{}" -s {} -p {}{}'.format(self._cli_prefix,
                                                                              self._log_dir,
                                                                              self._log_name,
                                                                              self._ip,
                                                                              self._file_limit,
                                                                              self._change_ports_to_string(),
                                                                              self._add_line_number)
        return ret

    def _get_netstat(self):
        netstat_cmd = "sudo netstat -tulpen | egrep ':{}'".format('|:'.join(map(str, self._ports)))
        try:
            netstat_table = self._ssh_connection.execute(netstat_cmd)
        except Exception:
            return ''
        zipped_table = self._parse_netstat_table(netstat_table[0])
        return self._pretty_printed(zipped_table)

    def _parse_netstat_table(self, netstat_table):
        lines = netstat_table.split('\n')
        protocols, local_ips, pids_and_program_names = ['Protocol'], ['Local IP'], ['PID/Program Name']
        for line in [line for line in lines if line]:
            columns = line.split()
            protocols.append(columns[0])
            local_ips.append(columns[3])
            pids_and_program_names.append(columns[-1])
        return zip(protocols, local_ips, pids_and_program_names)

    def _pretty_printed(self, zipped_table):
        fields = '{: <10s}   {: <30s}   {: <10s}'
        return '==============================================================\n' + \
               '\n'.join(fields.format(*row) for row in zipped_table) + \
               '\n==============================================================\n'
